        HelpPage(slug: "combining-paths", title: "Combining paths", group: "Objects", summary: "New shapes come from combining old ones.  Join fuses paths into one composite path whose sub-paths cut holes in one another; Union, Divide, Intersect, Punch, Crop and",
                 headings: ["Keeping the originals", "Join", "Union", "Divide", "Intersect", "Punch", "Crop", "Transparency", "Working with others"],
