        HelpPage(slug: "data-merge", title: "Data merge", group: "Automation and data", summary: "Data merge turns one designed page into many: a mailing label for every address in a list, a name badge for every attendee, a product card for every row a web service returns, a ticket with its own QR code for every order.  You design the page once, mark the places where the data goes, connect a source of records, and WireTuner produces a page -- or a printed sheet, or a PDF -- for each record.  The data itself stays where it lives: in a file, in a spreadsheet you paste from, behind a web API, or in a script you write.  The document only knows the names of the fields it expects and where each one goes.",
                 headings: ["How data merge works", "The Data panel", "Defining fields", "Placing fields in the document", "Connecting a data source", "Previewing records", "Merging", "Working with others"],
                 keywords: ["field", "source", "records", "record", "document", "data", "merge", "file", "choose", "fields", "name", "script", "panel", "object", "value", "every", "type", "preview", "placeholder", "block", "click", "code", "number", "image", "barcode", "sample", "options", "first", "credential", "connect", "same", "hosts", "team", "wiretuner", "date", "menu", "sheet", "everyone", "firstname", "shows"]),
        HelpPage(slug: "default-attributes", title: "Changing default attributes", group: "Objects", summary: "Every new object is born with the document's default attributes: a stroke, a fill, and any effects, exactly as the Object panel shows them when nothing is selected.  Change those and every object you draw from then on gets the new look.  The defaults belong to the document, so a collaborator opening it -- or you, on another Mac -- draws with the same defaults.",
                 headings: ["Changing the defaults", "Working with others"],
                 keywords: ["defaults", "object", "change", "document", "default", "panel", "attributes", "stroke", "fill", "draw", "same", "next", "nothing", "selected", "look", "another", "style", "changing", "changes", "every", "effects", "collaborator", "draws", "edit", "styles", "part", "born", "exactly", "shows", "gets", "belong", "opening", "todo", "screenshot", "showing", "deselect", "everything", "select", "none", "press"]),
        HelpPage(slug: "document-panel", title: "The Document panel", group: "Document setup", summary: "The Document panel is where a document's pages and its output settings live.  It shows the whole pasteboard in miniature, one thumbnail per page, and lets you set the size, orientation and bleed of the selected page, choose the resolution the document is prepared for, and add, remove and rearrange pages without leaving the panel.  Everything you change here is part of the document: collaborators see it as soon as it syncs, and it is remembered when you are offline.",
                 headings: ["Opening the Document panel", "Setting page options", "Printer resolution", "The pasteboard view", "Page commands in the Options menu", "Document units", "Working with others"],
                 keywords: ["document", "master", "size", "bleed", "panel", "selected", "pop-up", "unit", "pasteboard", "thumbnail", "orientation", "change", "sizes", "resolution", "click", "field", "custom", "objects", "units", "value", "settings", "button", "view", "choose", "buttons", "menu", "every", "setting", "same", "picas", "shows", "window", "printer", "type", "press", "return", "width", "order", "move", "child"]),
        HelpPage(slug: "document-view", title: "Setting the document view", group: "Basics", summary: "How you look at a document is separate from what is in it.  You can zoom from 6% to 25,600%, scroll anywhere on the pasteboard, turn the whole canvas to the angle your hand prefers, switch between drawing modes that trade fidelity for speed, open the same document in several windows, and save views by name so you can return to a detail with one click.  Everything on this page except named views is private to your Mac; named views are part of the document and are shared with your collaborators.",
                 headings: ["The View menu", "Zooming", "Scrolling", "Rotating the canvas", "Trackpad, mouse and tablet gestures", "Drawing modes", "Multiple views of one document", "Named views", "Preview in Browser", "Working with others"],
                 keywords: ["view", "zoom", "canvas", "document", "rotate", "named", "views", "click", "window", "mode", "magnification", "preview", "choose", "scroll", "drawing", "shift", "turn", "keyline", "drag", "tool", "same", "name", "menu", "custom", "fast", "guides", "trackpad", "current", "status", "mouse", "return", "objects", "below", "browser", "rulers", "object", "screen", "angle", "open", "option"]),
        HelpPage(slug: "editing-colors", title: "Editing colors", group: "Color", summary: "Editing color in WireTuner happens at two levels.  Edit a swatch and every object that uses it changes -- that is what naming a color is for.  Edit the objects with the Colors extensions and each object gets its own adjusted, unnamed color while the swatches stay as they were.  This page covers both, and the global replace that swaps one color for another throughout the artwork.",
                 headings: ["Editing a named color", "Brightening and dulling colors", "Controlling color values", "Converting to grayscale", "Making global color changes", "Working with others"],
                 keywords: ["color", "colors", "swatch", "objects", "extensions", "every", "replace", "swatches", "object", "name", "change", "panel", "step", "tints", "black", "edit", "spot", "choose", "list", "same", "named", "unnamed", "adjust", "cmyk", "selection", "command", "select", "results", "adjusted", "another", "everything", "selected", "apply", "redefine", "mixer", "onto", "white", "cannot", "process", "menu"]),
        HelpPage(slug: "editing-paths", title: "Editing paths", group: "Drawing", summary: "Once a path exists you can move its points, change what kind of points they are, pull its handles, add and remove points, cut it apart, rub parts of it out, push its segments around with the Freeform tool, and thin it out with Simplify.  The Pointer and Subselect tools do the fine work; the Freeform, Knife and Eraser tools do the broad strokes; the Object panel gives every point a numeric address.",
                 headings: ["Selecting and moving points", "Adjusting handles", "Changing points in the Object panel", "Adding and deleting points and segments", "Reshaping with the Freeform tool", "Splitting paths", "Erasing", "Simplifying and cleaning up", "Removing overlap", "Reversing direction", "Working with others"],
                 keywords: ["path", "point", "points", "pointer", "click", "paths", "tool", "handles", "push", "choose", "drag", "selected", "pull", "segment", "curve", "select", "handle", "eraser", "corner", "reshape", "move", "freeform", "knife", "across", "keeps", "length", "becomes", "fill", "remove", "simplify", "dragging", "press", "open", "size", "modify", "overlap", "direction", "edits", "subselect", "every"]),
        HelpPage(slug: "editing-text", title: "Editing text", group: "Type", summary: "Editing text means selecting some of it and changing it: retyping, deleting, inserting special characters, fixing spelling, or finding and replacing across the document.  You do it directly on the page with the Text tool, or in the Text Editor window when the text is hard to reach -- tiny, pale, rotated, or full of invisible characters.  Formatting is the subject of Setting type specifications and the pages after it.",
                 headings: ["Selecting text", "Editing on the page", "The Text Editor window", "Special characters", "Smart quotes", "Checking spelling", "Finding and replacing text", "Converting case", "Working with others"],
                 keywords: ["block", "spelling", "tool", "type", "words", "word", "editor", "replace", "window", "find", "document", "select", "edit", "character", "option", "space", "characters", "paragraph", "every", "line", "shift", "small", "typing", "selection", "point", "choose", "preference", "same", "lowercase", "case", "letters", "special", "whole", "cols", "pointer", "next", "dash", "sentence", "editing", "formatting"]),
        HelpPage(slug: "expand-stroke", title: "Expanding a stroke", group: "Objects", summary: "Expand Stroke turns the stroke of a path into a filled shape of its own.  A two-point line becomes a closed, four-point rectangle; a closed path becomes a composite path whose outer and inner contours trace the stroke's two edges.  Once expanded, the former stroke can take any fill -- a gradient, a lens, a tiled pattern -- and its outline can be edited point by point.",
                 headings: ["Working with others"],
                 keywords: ["stroke", "path", "expand", "width", "paths", "original", "closed", "miter", "same", "filled", "becomes", "expanded", "fill", "point", "sheet", "join", "limit", "selected", "click", "operations", "round", "combining", "attributes", "edit", "turns", "shape", "two-point", "line", "four-point", "rectangle", "composite", "whose", "outer", "inner", "contours", "trace", "edges", "once", "former", "take"]),
        HelpPage(slug: "export-bitmap", title: "Exporting bitmap images", group: "Saving and exporting", summary: "A bitmap export renders your artwork to pixels.  You choose the resolution, the smoothing, whether the background is transparent, the color mode and the format's own settings; WireTuner draws the page, area or selection exactly as on screen and writes PNG, JPEG, WebP, HEIC, AVIF, GIF, TIFF, Photoshop, BMP or Targa.  Everything renders -- transparency, blend modes, live and raster effects, placed images with their own transparency -- because pixels can hold anything.",
                 headings: ["Options common to every bitmap format", "Alpha channels and transparency", "PNG", "JPEG", "WebP, HEIC and AVIF", "GIF", "TIFF", "Photoshop (PSD)", "BMP and Targa", "Bitmap export defaults", "Exporting many pages or many sizes", "Working with others"],
                 keywords: ["export", "layer", "color", "colors", "background", "default", "transparent", "alpha", "profile", "pixels", "transparency", "document", "option", "layers", "writes", "file", "files", "cols", "effect", "palette", "wiretuner", "edges", "cmyk", "display", "keep", "bitmap", "format", "jpeg", "options", "sheet", "channel", "objects", "image", "every", "artwork", "resolution", "exporting", "pixel", "none", "embed"]),
        HelpPage(slug: "export-formats", title: "About export file formats", group: "Saving and exporting", summary: "Exporting writes a copy of your artwork, a page, a selection or the text of a document in a format another program can open.  The document itself stays in the cloud; an export is a snapshot of it in someone else's language.  This page lists every format WireTuner writes and what each is good for.  The procedures are on Exporting files, and the options per format on Exporting vector artwork, Exporting bitmap images, Exporting PDF files and Exporting text.",
                 headings: ["Formats", "Choosing a format", "Web formats", "Working with others"],
                 keywords: ["transparency", "exporting", "format", "export", "images", "illustrator", "alpha", "artwork", "document", "wiretuner", "file", "graphics", "lossless", "files", "print", "page-layout", "colors", "jpeg", "photographs", "webp", "avif", "photoshop", "millions", "another", "else", "cols", "programs", "paths", "layers", "optional", "tiff", "size", "matters", "lossy", "color", "compression", "browsers", "channel", "software", "image"]),
        HelpPage(slug: "export-pdf", title: "Exporting PDF files", group: "Saving and exporting", summary: "PDF is the format to reach for when the artwork has to arrive intact: at a print shop, in a page-layout program, in someone's mail.  WireTuner writes PDFs that keep text as text, vector as vector, transparency live, spot colors named, fonts embedded and every page in one file, and it can produce the PDF/X files printers ask for, with bleed and printer's marks.",
                 headings: ["General", "Compression", "Fonts", "Color", "Pages and marks", "Interactive", "PDF/X", "What the PDF keeps", "Working with others"],
                 keywords: ["document", "profile", "colors", "file", "fonts", "bleed", "export", "spot", "default", "display", "every", "marks", "object", "written", "images", "cols", "destination", "wiretuner", "writes", "files", "objects", "options", "option", "effect", "everything", "stays", "names", "cmyk", "size", "transparency", "embedded", "printer", "output", "sheet", "later", "keeps", "standard", "requires", "always", "notes"]),
        HelpPage(slug: "export-text", title: "Exporting text", group: "Saving and exporting", summary: "The text in a document -- a story, a text block, a selection of words -- can leave WireTuner three ways: through the Export sheet as an RTF or plain text file, through Copy and Paste, and by dragging.  RTF keeps the formatting a word processor understands; plain text keeps the words.",
                 headings: ["Exporting a text file", "Copying and dragging text", "What formatting is preserved", "Working with others"],
                 keywords: ["export", "plain", "block", "characters", "styles", "file", "choose", "rich", "inline", "document", "keeps", "word", "exports", "selected", "graphics", "converted", "paragraph", "breaks", "story", "words", "copy", "formatting", "cols", "blocks", "order", "line", "type", "paragraphs", "kept", "font", "caps", "tables", "effects", "wiretuner", "sheet", "paste", "dragging", "range", "linked", "first"]),
        HelpPage(slug: "export-vector", title: "Exporting vector artwork", group: "Saving and exporting", summary: "Vector formats keep your artwork as paths, text and colors that the receiving program can scale, edit and print at any resolution.  WireTuner writes EPS, Adobe Illustrator, SVG and DXF as vector formats; PDF, the most capable of them, has its own page (Exporting PDF files).  This page describes the options of each, and then the rules that apply to all of them: what happens to effects, transparency, blends, gradients and overprint when a format cannot carry them as drawn.",
                 headings: ["EPS options", "Adobe Illustrator options", "SVG options", "DXF options", "How effects and transparency export [[flattening]]", "Working with others"],
                 keywords: ["writes", "document", "effects", "file", "illustrator", "fonts", "paths", "wiretuner", "files", "transparency", "export", "names", "raster", "object", "keep", "options", "format", "default", "images", "artwork", "resolution", "gradients", "postscript", "level", "rendered", "vector", "colors", "exporting", "overprint", "embed", "font", "outlines", "layers", "effect", "every", "size", "info", "live", "layer", "path"]),
        HelpPage(slug: "exporting-colors", title: "Exporting and sharing colors", group: "Color", summary: "A palette you have built is worth keeping.  WireTuner lets you export named colors as a color library file for other documents and other applications, copy colors directly between open documents, and -- new in WireTuner -- keep a team color library in the cloud that every document on your team can draw from.",
                 headings: ["Exporting a color library", "Sharing colors between documents", "Team color libraries", "Working with others"],
                 keywords: ["library", "document", "colors", "team", "color", "swatches", "open", "choose", "libraries", "export", "file", "options", "menu", "wiretuner", "documents", "list", "update", "named", "every", "name", "format", "swatch", "copy", "panel", "sheet", "tick", "wtcolors", "click", "changes", "keeps", "applications", "cloud", "tints", "exported", "base", "save", "appears", "import", "artwork", "another"]),
        HelpPage(slug: "exporting", title: "Exporting files", group: "Saving and exporting", summary: "File Export… writes the document, some of its pages, an area of the pasteboard or just the selected objects to a file in one of the formats on xref:export-formats.adoc[About export file formats].  The same dialog serves every format; the Options… button opens the settings that belong to the format you picked.  Once you have exported, File Export Again repeats the export to the same file, Quick Export skips the dialog altogether using a preset, dragging objects out of the window onto the Finder or into another app exports them on the spot, and the Share menu sends an export straight to another app or another person.",
                 headings: ["Exporting a document", "File names for several pages [[naming]]", "Exporting again", "Export presets", "Quick Export", "Dragging artwork out", "The Share menu and Services", "Working with others"],
                 keywords: ["export", "file", "document", "format", "preset", "sheet", "objects", "same", "name", "wiretuner", "menu", "options", "choose", "selected", "finder", "exports", "artwork", "exporting", "option", "formats", "share", "pattern", "area", "every", "settings", "another", "changes", "layers", "convert", "presets", "button", "once", "exported", "again", "quick", "window", "goes", "several", "output", "hidden"]),
        HelpPage(slug: "extensions", title: "Extensions", group: "Basics", summary: "Extensions are WireTuner's specialized commands and tools -- path operations, color utilities, distortion tools, chart pictographs, animation helpers.  They are all built in, organized under the Extensions menu and on two toolbars, and can be switched off individually if you never use them.",
                 headings: ["Using extensions", "The Extensions menu", "The Extension Tools toolbar", "The Extension Operations toolbar", "Managing extensions", "Working with others"],
                 keywords: ["extensions", "extension", "tools", "colors", "path", "tool", "operations", "toolbars", "choose", "color", "chart", "menu", "operation", "name", "remove", "direction", "click", "panel", "repeat", "last", "same", "editing", "paths", "blend", "union", "expand", "stroke", "inset", "wiretuner", "animation", "submenu", "window", "selection", "nothing", "double-click", "release", "layers", "pictograph", "correct", "overlap"]),
        HelpPage(slug: "external-editors", title: "Editing images in other applications", group: "Imported artwork", summary: "WireTuner places, arranges, crops and tints images but does not edit their pixels.  For retouching, you hand an image to an image editor -- Photoshop, Pixelmator Pro, Affinity Photo, Acorn, or simply Preview -- and WireTuner takes the result back the moment you save.  For the common housekeeping tasks that used to need an external editor (changing the file format, reducing the file size, resampling to a sensible resolution, converting to grayscale) WireTuner has its own Optimize Image sheet.",
                 headings: ["Editing an image in another application", "Optimizing an image", "Working with others"],
                 keywords: ["image", "editor", "wiretuner", "pixels", "format", "default", "size", "editing", "edit", "file", "application", "panel", "images", "resolution", "back", "grayscale", "optimize", "kept", "same", "jpeg", "save", "shows", "document", "saved", "pixel", "effective", "color", "tiff", "stored", "external", "choose", "submenu", "click", "lists", "open", "confirm", "replaces", "keep", "several", "session"]),
        HelpPage(slug: "extrude", title: "Extruding objects", group: "Effects", summary: "The Extrude tool turns a flat shape into a solid: it sweeps the shape away from you toward a vanishing point and draws the sides, shaded as if lit.  The original 2D shape stays inside the extrusion, fully editable -- change its points, its fill or its stroke and the solid follows. You can rotate the solid in three dimensions, give its sides a profile so it becomes a bevelled plaque or a turned spindle, twist it, choose flat, shaded or wireframe sides, and place lights. Several extruded objects can share one vanishing point so a scene reads as a single perspective.",
                 headings: ["Extruding", "Editing on the canvas", "Editing in the Object panel", "Working with others"],
                 keywords: ["object", "point", "extrusion", "vanishing", "profile", "extrude", "extruded", "tool", "shape", "sides", "flat", "select", "depth", "solid", "drag", "rotation", "choose", "shaded", "points", "centre", "axis", "light", "toward", "draws", "inside", "pointer", "modify", "tools", "panel", "surface", "along", "path", "share", "same", "paths", "stroked", "click", "copy", "position", "circle"]),
        HelpPage(slug: "file-info", title: "Adding file information", group: "Saving and exporting", summary: "A document can carry information about itself -- who made it, what it shows, who owns the rights, which keywords describe it -- and WireTuner writes that information into every file it exports that has a place for it: PDF, SVG, EPS, PNG, JPEG, TIFF, WebP, HEIC, AVIF and PSD.  The fields follow the IPTC Core standard, so a picture desk, a digital asset manager or Adobe Bridge reads them without help.",
                 headings: ["Adding document information", "Where the information goes", "Working with others"],
                 keywords: ["document", "sheet", "keywords", "fields", "title", "creator", "information", "rights", "every", "file", "field", "name", "work", "same", "both", "info", "description", "copyright", "packet", "data", "describe", "jpeg", "tiff", "iptc", "core", "export", "block", "metadata", "shows", "webp", "heic", "avif", "follow", "asset", "reads", "change", "sections", "library", "empty", "exported"]),
        HelpPage(slug: "fill-attributes", title: "Fills", group: "Strokes and fills", summary: "A fill colors the inside of a path.  WireTuner offers seven kinds of fill, chosen from the",
                 headings: ["Basic fills", "Custom fills", "Lens fills", "Pattern fills", "Textured fills", "Tiled fills", "Working with others"],
                 keywords: ["fill", "color", "object", "lens", "pattern", "choose", "beneath", "objects", "pop-up", "tile", "type", "selected", "angle", "custom", "fills", "drag", "noise", "colors", "textured", "artwork", "every", "same", "black", "white", "random", "snapshot", "change", "panel", "tiled", "interior", "strokes", "shows", "drawn", "apply", "path", "chosen", "editor", "basic", "bitmap", "across"]),
        HelpPage(slug: "find-replace", title: "Finding, replacing and selecting by attribute", group: "Objects", summary: "The Find & Replace Graphics panel makes changes across a whole drawing at once: recolor every object that uses a color, thicken every hairline, rotate every star about its own center, resample every blend.  Its second tab, Select, finds objects by the same attributes and selects them so you can do anything you like to them.",
                 headings: ["Find & Replace tab", "Select tab", "Working with others"],
                 keywords: ["objects", "color", "object", "attribute", "stroke", "path", "replace", "find", "selection", "fill", "width", "panel", "every", "select", "finds", "change", "choose", "click", "font", "style", "size", "shape", "changes", "rotate", "blend", "same", "range", "sample", "graphics", "center", "found", "document", "settings", "changed", "tints", "match", "scale", "steps", "given", "whose"]),
        HelpPage(slug: "font-export", title: "Generating and exchanging fonts", group: "Typeface documents", summary: "A typeface document becomes a font with File Generate Fonts….  WireTuner checks the font, flattens every glyph's artwork into clean outlines, compiles the metrics, kerning and features, and writes OTF, TTF or WOFF2 files -- or a UFO package for other font editors.  The same sheet installs the font on your Mac for testing.  In the other direction, an existing OTF, TTF or UFO can be opened as a new typeface document to start from.",
                 headings: ["Generating fonts", "Installing for testing", "UFO packages", "Opening an existing font", "Working with others"],
                 keywords: ["font", "glyph", "file", "glyphs", "document", "fonts", "every", "choose", "feature", "generate", "name", "kerning", "sheet", "components", "mark", "artwork", "outlines", "names", "open", "typeface", "wiretuner", "test", "generated", "written", "warning", "package", "format", "default", "overlaps", "contours", "install", "error", "info", "kern", "read", "become", "metrics", "features", "testing", "converted"]),
        HelpPage(slug: "font-info", title: "Font Info", group: "Typeface documents", summary: "the size of its em, the vertical metrics that every glyph canvas draws as lines, the OS/2 classification that applications use to sort it into menus, and its license.  Open it with Font Font Info… (Cmd+Option+F) from anywhere in a typeface document.  Every value in it is part of the document and is shared with everyone editing it.",
                 headings: ["Names", "Metrics", "OS/2", "Guides", "License", "Working with others"],
                 keywords: ["font", "every", "default", "glyph", "change", "name", "lines", "style", "applications", "sheet", "metrics", "value", "ascender", "descender", "line", "names", "canvas", "license", "pane", "changes", "family", "same", "height", "metric", "info", "size", "document", "units", "grid", "draws", "cols", "field", "meaning", "because", "free", "baseline", "x-height", "advance", "width", "listed"]),
        HelpPage(slug: "font-substitution", title: "Missing fonts", group: "Document setup", summary: "When you open a document that uses fonts not installed on your Mac, WireTuner shows the Missing Fonts sheet and lets you choose what to display in their place.  You can substitute a font -- a stand-in on your Mac only, leaving the document untouched -- or replace it, which changes the document for everyone.  If a team font library is available, fonts in it are fetched automatically and the sheet never appears for them.",
                 headings: ["What happens when a font is missing", "The Missing Fonts sheet", "The substitution table", "Team font library", "Working with others"],
                 keywords: ["font", "fonts", "document", "missing", "substitute", "sheet", "team", "library", "click", "wiretuner", "shows", "everyone", "name", "default", "substitutions", "same", "open", "choose", "replace", "available", "fetched", "keeps", "activated", "style", "nothing", "replacing", "replacement", "installed", "changes", "never", "panel", "badge", "reflow", "screen", "changed", "exports", "real", "lists", "select", "every"]),
        HelpPage(slug: "freeform", title: "Drawing freeform paths", group: "Drawing", summary: "The three tools in the Pencil group draw paths that follow your hand: the Pencil draws a plain line, the Variable Stroke Pen draws a filled shape whose width swells and thins like a brush, and the Calligraphic Pen draws a filled shape whose width depends on the direction of the stroke, like a broad-nib pen.  All three turn the motion of the pointer into a smooth path with as few points as the precision you choose allows, and all three read pressure from a pen tablet or an Apple Pencil.",
                 headings: ["Pencil", "Variable Stroke Pen", "Calligraphic Pen", "Drawing with a pen tablet", "Working with others"],
                 keywords: ["stroke", "pencil", "path", "width", "variable", "draw", "pressure", "tool", "calligraphic", "points", "keys", "draws", "tools", "precision", "choose", "fill", "option", "angle", "three", "paths", "line", "filled", "shape", "whose", "tablet", "options", "dotted", "drag", "dragging", "straight", "segment", "mouse", "overlap", "drawn", "double-click", "sheet", "click", "color", "canvas", "release"]),
        HelpPage(slug: "glyph-editing", title: "Editing glyphs", group: "Typeface documents", summary: "A glyph opens as a tab in the typeface window with its own canvas.  The canvas is the ordinary WireTuner drawing canvas -- every tool in the Tools panel works, every panel applies -- with three differences: it is measured in font units, it shows the font's metric lines and the glyph's own width handles, and it can contain components (other glyphs placed by reference) and anchors (named points where accents attach).  Below the artwork a preview strip sets the glyph in a line of text so you can judge it in context while you draw.",
                 headings: ["The glyph canvas", "Components", "Anchors", "Checking a glyph", "The preview strip", "Working with others"],
                 keywords: ["glyph", "font", "component", "anchor", "width", "name", "canvas", "every", "units", "points", "lines", "artwork", "grid", "components", "point", "paths", "mark", "panel", "shows", "guides", "outline", "base", "advance", "move", "generator", "choose", "same", "side", "drawing", "metric", "glyphs", "anchors", "preview", "strip", "line", "left", "show", "view", "snap", "whole"]),
        HelpPage(slug: "glyph-grid", title: "The glyph grid", group: "Typeface documents", summary: "The glyph grid is the main view of a typeface document: one cell per glyph, showing its outline, its name and the character it encodes.  It is where you add and remove glyphs, rename and re-encode them, select several to act on at once, and open one for drawing.  It takes the place of the page thumbnails of an illustration document.",
                 headings: ["Reading the grid", "Ordering and encodings", "Adding glyphs", "Selecting glyphs", "Opening, renaming and removing glyphs", "Acting on several glyphs", "Working with others"],
                 keywords: ["glyph", "glyphs", "name", "character", "cell", "artwork", "codepoint", "selected", "grid", "choose", "unicode", "sheet", "component", "same", "view", "remove", "rename", "open", "order", "components", "width", "edit", "select", "shows", "mark", "anchors", "cells", "range", "eacute", "codepoints", "paste", "every", "bearing", "document", "outline", "empty", "encoding", "latin-", "color", "unencoded"]),
        HelpPage(slug: "gradients", title: "Gradients", group: "Strokes and fills", summary: "A Gradient fill blends smoothly between two or more colors.  You choose the colors on a ramp in the Object panel and shape the blend with handles on the object itself: a start point where the first color sits and one or two end points that set how far, in which direction, and how wide the blend runs.  Six gradient types decide the blend's geometry, and a behavior decides what happens past the end points.",
                 headings: ["Applying a gradient", "Gradient types", "Gradients on groups, text and blends", "Working with others"],
                 keywords: ["gradient", "color", "point", "ramp", "drag", "blend", "swatch", "start", "colors", "object", "fill", "swatches", "panel", "handles", "both", "move", "blends", "choose", "shape", "radial", "center", "points", "runs", "type", "linear", "contour", "count", "dragging", "drop", "stop", "first", "behavior", "fills", "pop-up", "logarithmic", "rectangle", "cone", "onto", "modifier", "option"]),
        HelpPage(slug: "graphic-hose", title: "Graphic Hose", group: "Drawing", summary: "The Graphic Hose sprays artwork along the path you drag: leaves along a branch, stars across a sky, a row of footprints.  A hose is a set of up to ten pieces of artwork -- paths, groups, bitmaps, blends, text, symbols -- and a set of options that decide the order, spacing, size and rotation of each copy as you spray.  WireTuner ships with a collection of hoses, and you can make your own from anything in a document.",
                 headings: ["Choosing a hose", "Spraying", "Hose options", "Making and editing hoses", "Working with others"],
                 keywords: ["hose", "graphic", "library", "hoses", "document", "object", "choose", "click", "pop-up", "objects", "options", "artwork", "drag", "spray", "sheet", "tool", "sets", "spacing", "wiretuner", "every", "places", "random", "edit", "along", "order", "copy", "double-click", "contents", "spraying", "symbol", "angle", "kept", "bitmaps", "size", "rotation", "ships", "ordinary", "current", "release", "sprayed"]),
        HelpPage(slug: "grid-guides", title: "Grid and guides", group: "Document setup", summary: "The grid and guides are non-printing alignment aids.  The grid is a regular lattice of dots behind the whole pasteboard; guides are horizontal and vertical lines you place on pages.  Objects can snap to either, and to the points of other objects.  Grid spacing and the guides themselves are part of the document and shared; whether you see them, and whether your dragging snaps, are personal settings.  Guides that appear on their own while you drag -- smart guides -- are a different thing, described with Moving objects.",
                 headings: ["Colors", "The grid", "Guides", "Snapping to points and objects", "Working with others"],
                 keywords: ["guides", "grid", "guide", "snapping", "choose", "view", "click", "snap", "drag", "objects", "position", "dragging", "document", "object", "turn", "horizontal", "smart", "size", "point", "sheet", "vertical", "snaps", "settings", "default", "show", "edit", "layer", "layers", "pasteboard", "points", "every", "dragged", "onto", "check", "mark", "type", "relative", "rulers", "paths", "master"]),
        HelpPage(slug: "grouping", title: "Grouping objects", group: "Objects", summary: "Grouping ties objects together so that they move, transform and take attributes as one.  A group keeps its members' stacking order and relative positions; groups nest inside groups; and a member can still be reached inside the group with the Subselect tool.  Ungrouping sets the members free again.",
                 headings: ["Grouping and ungrouping", "Nesting", "Attributes of a group", "Working inside groups", "Working with others"],
                 keywords: ["group", "members", "member", "objects", "object", "groups", "subselect", "selected", "layer", "attributes", "inside", "modify", "select", "transform", "order", "ungroup", "choose", "edit", "strokes", "move", "stacking", "ungrouping", "same", "another", "fills", "effects", "change", "stroke", "shows", "paste", "grouping", "take", "relative", "nest", "still", "tool", "single", "cols", "active", "layers"]),
        HelpPage(slug: "halftones", title: "Halftones", group: "Printing", summary: "A halftone screen is how a printing press or imagesetter renders a tint: a pattern of dots (or lines, or ellipses) whose size varies with the ink coverage, laid at an angle and a frequency. The Print dialog sets the screen for each plate of the whole document (Printing).  The Halftones panel lets you give particular objects a screen of their own -- a coarse line screen on a background tint for effect, a finer screen on a detailed logo -- that overrides the document's screen wherever those objects print.",
                 headings: ["Applying a halftone screen to objects", "Overriding object screens at print time", "Overprint", "Working with others"],
                 keywords: ["screen", "object", "document", "objects", "angle", "print", "frequency", "panel", "screens", "halftone", "plate", "value", "every", "fill", "lines", "dialog", "halftones", "line", "effect", "separations", "selected", "choose", "shape", "default", "attributes", "stroke", "printing", "press", "imagesetter", "tint", "whose", "whole", "printer", "settings", "same", "degrees", "select", "typing", "dragging", "inch"]),
        HelpPage(slug: "history", title: "Version history", group: "Collaboration", summary: "Every change anyone makes to a document is kept, with who made it and when.  Version history is where you look at that record: to see what happened while you were away, to find out who moved the logo, to name the state you are about to send to the printer, and to get back to how things were on Tuesday -- without stopping anyone else from working.  There is no Save; history is written as you draw (Saving).",
                 headings: ["The History panel", "Naming a version", "Viewing a version", "Restoring a version", "Comparing two versions", "Who changed this object", "Undo, history and other people", "How long history is kept", "Working with others"],
                 keywords: ["restore", "history", "version", "changes", "name", "document", "change", "panel", "named", "window", "objects", "state", "back", "view", "copy", "every", "timeline", "versions", "object", "click", "compare", "review", "current", "anyone", "logo", "comments", "delete", "live", "kept", "look", "person", "hover", "offline", "client", "retention", "older", "read-only", "attribute", "else", "working"]),
        HelpPage(slug: "image-color", title: "Managing image color", group: "Color management", summary: "A bitmap image is a grid of numbers, and the numbers mean nothing until a profile says which device produced them.  A photograph from a camera, a scan, and a screenshot may all say \"R=200 G=30 B=40\" and mean three slightly different reds.  WireTuner lets you tell it, image by image, which profile the pixels should be read through -- its source profile -- and which rendering intent to use when the image is proofed or printed.  Assigning a source profile never changes the pixels; it changes how they are shown and how they will be converted for output.",
                 headings: ["Assigning versus converting", "Setting an image's source profile", "Embedded profiles on import", "Missing profiles", "Working with others"],
                 keywords: ["profile", "image", "document", "default", "embedded", "read", "source", "images", "changes", "same", "pixels", "assigning", "color", "file", "object", "wiretuner", "intent", "assigned", "cmyk", "menu", "mean", "nothing", "different", "time", "without", "every", "data", "later", "panel", "grayscale", "choose", "bundled", "shows", "preference", "sheet", "import", "numbers", "until", "photograph", "screenshot"]),
        HelpPage(slug: "import-formats", title: "Import file formats", group: "Imported artwork", summary: "WireTuner imports vector drawings, bitmap images, placed files and text.  This page lists every format the Import sheet accepts, what each one turns into once it is in the document, and the options the Options… button offers for it.  The mechanics of placing a file -- the Import command, dragging from the Finder, pasting -- are on Importing artwork.",
                 headings: ["Format summary", "PDF", "Adobe Illustrator", "SVG", "AutoCAD DXF", "EPS", "SVG animations", "Bitmap formats", "Working with others"],
                 keywords: ["file", "placed", "import", "paths", "image", "options", "wiretuner", "images", "preview", "default", "postscript", "alpha", "files", "illustrator", "converted", "groups", "imported", "notes", "editable", "objects", "animation", "format", "importing", "artwork", "read", "clipping", "convert", "imports", "document", "strokes", "fills", "tiff", "jpeg", "photoshop", "object", "size", "edit", "layers", "color", "vector"]),
        HelpPage(slug: "importing-text", title: "Importing text", group: "Type", summary: "Text written elsewhere comes into WireTuner three ways: importing a file, pasting, or dragging text from another application onto the page.  Rich Text (RTF) files arrive with their formatting; plain text arrives in the current default text attributes.  Fonts the file names but your Mac does not have go through font substitution (Font substitution).  Exporting text back out is on Exporting text.",
                 headings: ["Importing a text file", "Pasting", "Dragging text in", "Encoding and scripts", "Working with others"],
                 keywords: ["block", "import", "file", "wiretuner", "point", "plain", "drag", "paragraph", "pasting", "another", "application", "onto", "rtfd", "pointer", "auto-expanding", "styles", "utf-", "paste", "dropping", "encoding", "rich", "files", "arrive", "formatting", "current", "default", "attributes", "fonts", "names", "font", "substitution", "exporting", "choose", "click", "create", "size", "inside", "drop", "format", "leaders"]),
        HelpPage(slug: "importing", title: "Importing artwork", group: "Imported artwork", summary: "Artwork made elsewhere -- a photograph, a logo drawn in another application, a PDF page, a scanned sketch -- comes into a WireTuner document through the Import command, by dragging a file in from the Finder, or by pasting.  Whatever the route, the artwork ends up as ordinary objects on the current layer: vector files become paths and groups you can edit with every tool in the book, and bitmap files become image objects that you can move, scale, crop, tint and trace.  This page covers the ways to bring a file in and what happens to it once it arrives; Import file formats lists every format and its options, and Working with bitmap images covers what you can do with an image afterwards.",
                 headings: ["What happens to imported artwork", "Importing with the Import command", "Dragging files from the Finder", "Pasting", "From another app's Share menu", "Watching an image upload", "Working with others"],
                 keywords: ["file", "import", "files", "image", "wiretuner", "document", "artwork", "layer", "placed", "format", "pixels", "size", "bitmap", "imported", "once", "options", "vector", "edit", "preview", "until", "pointer", "name", "placeholder", "dragging", "objects", "current", "every", "scale", "images", "pixel", "importing", "appears", "natural", "onto", "same", "finder", "move", "cannot", "object", "resolution"]),
        HelpPage(slug: "index", title: "{product-full}: {book}", group: "", summary: "",
                 headings: [],
                 keywords: []),
        HelpPage(slug: "inset-path", title: "Insetting a path", group: "Objects", summary: "Inset Path makes copies of a closed path that follow its outline a set distance inside or outside it -- one copy, or a series of them stepping inward like contour lines.  The copies keep the original's attributes, so an inset with several steps and a gradient fill on each gives a quick concentric effect.",
                 headings: ["Working with others"],
                 keywords: ["path", "inset", "original", "paths", "distance", "steps", "copies", "closed", "inside", "outside", "stepping", "inward", "sheet", "click", "operations", "replaces", "wider", "gaps", "near", "narrower", "ones", "toward", "center", "values", "miter", "combining", "stroke", "follow", "outline", "copy", "series", "contour", "lines", "keep", "attributes", "several", "gradient", "fill", "gives", "quick"]),
        HelpPage(slug: "inspect", title: "Inspect mode", group: "Collaboration", summary: "Inspect mode is the document with its ruler out.  Instead of drawing, you point: hover an object and its size appears; hover with something selected and the distances between the two appear; click and a panel lists everything about the object -- its colors in whatever notation you need, its stroke and fills, its type settings -- with a button beside each value that copies it.  A developer building the screen you designed gets the numbers without asking; a client reviewing the poster gets to look without the risk of nudging something; and a viewer can copy an object out as SVG, CSS, Swift or PNG without an export dialog.  Nothing you do in Inspect mode changes the document, so it is the mode WireTuner opens in for anyone whose role is viewer.",
                 headings: ["Entering and leaving Inspect mode", "Measuring by hovering", "The Inspect panel", "Units and scale", "Copying as code", "Copying as PNG", "Links to an object", "Working with others"],
                 keywords: ["object", "inspect", "mode", "panel", "document", "selection", "color", "copy", "scale", "name", "colors", "button", "every", "link", "selected", "pointer", "size", "click", "opens", "choose", "chosen", "units", "code", "snippet", "hover", "notation", "stroke", "fills", "value", "without", "export", "measurement", "view", "unit", "select", "swatch", "custom", "instead", "something", "copies"]),
        HelpPage(slug: "interactivity", title: "Adding interactivity", group: "Web and animation", summary: "A document can behave like a small clickable prototype: click an arrow and the next page appears, click a logo and the company's site opens.  WireTuner keeps this to two things an object can do when clicked -- go to a page of the document, or open a link -- because those are the two that every output format can honor.  A PDF opens the page or the URL; an SVG or a published web page follows the anchor; View Preview in Browser lets you click through before exporting.  Page links are set in the Navigation panel or drawn with the Link tool.",
                 headings: ["Setting what happens on click", "The Link tool", "Links in exported files", "Working with others"],
                 keywords: ["link", "object", "links", "tool", "click", "navigation", "panel", "badge", "choose", "html", "target", "shows", "drag", "browser", "objects", "pointer", "group", "href", "page-", "small", "published", "view", "preview", "window", "nothing", "same", "release", "document", "clickable", "opens", "wiretuner", "open", "every", "output", "format", "follows", "exporting", "cols", "pop-up", "menu"]),
        HelpPage(slug: "kerning-metrics", title: "Kerning and metrics", group: "Typeface documents", summary: "Spacing is half of a typeface.  The Metrics window is where you set it: type a word or a line, see it set in your glyphs, and drag to adjust each glyph's side bearings and advance width, and the kerning between particular pairs.  Kerning can be set pair by pair or, more efficiently, between kerning classes -- groups of glyphs that space alike, so one value covers T against every lowercase a-shaped letter.  Everything here is generated into the font's kern feature automatically (OpenType features).",
                 headings: ["The Metrics window", "The Kerning Classes editor", "Automatic kerning", "Spacing overview", "Working with others"],
                 keywords: ["class", "glyph", "pair", "kern", "classes", "value", "glyphs", "left", "kerning", "metrics", "window", "shows", "right", "type", "line", "width", "side", "every", "table", "field", "both", "drag", "advance", "features", "setting", "bearing", "same", "current", "name", "dragging", "spacing", "font", "option", "pop-up", "grid", "origin", "click", "column", "change", "matrix"]),
        HelpPage(slug: "layers", title: "Using layers", group: "Layers, symbols and styles", summary: "Layers split an illustration into stacked planes, the way a traditional illustrator draws the parts of a picture on separate sheets of tracing film.  Every object sits on exactly one layer, each layer keeps its own front-to-back order of objects, and the layers themselves stack in the order the Layers panel shows them.  A new document has three layers: Foreground, where drawing and importing happen until you choose another layer; Guides, which holds ruler guides and guide paths; and Background, a non-printing layer for reference material.  You can hide, lock, reorder, merge, recolor and remove layers, and you can decide which ones print.",
                 headings: ["The Layers panel", "Creating layers", "Selecting layers and the objects on them", "Moving objects between layers", "Reordering layers", "Merging layers", "Removing layers", "Showing and hiding layers", "Preview and Keyline per layer", "Locking and unlocking layers", "The Guides layer and guide paths", "Layer highlight colors", "Working with others"],
                 keywords: ["layer", "layers", "objects", "name", "panel", "guides", "color", "selected", "choose", "active", "click", "object", "onto", "move", "select", "every", "document", "guide", "merge", "above", "everything", "path", "drag", "hide", "options", "menu", "draw", "circle", "edit", "foreground", "background", "lock", "remove", "separator", "column", "below", "same", "check", "mark", "keyline"]),
        HelpPage(slug: "library", title: "Using the Library and symbols", group: "Layers, symbols and styles", summary: "The Library panel stores symbols: artwork you keep once and place many times.  Each placed copy is an instance that follows its symbol -- edit the symbol and every instance changes with it -- while keeping its own position, rotation, scale and URL.  Symbols keep repeated elements (logos, icons, map markers, brush tips) consistent and light.  The Library also lists the document's master pages (Working with master pages) and, when your team has set them up, shared team libraries that any document can draw on.",
                 headings: ["The Library panel", "Creating symbols", "Placing and modifying instances", "Overriding parts of an instance", "Editing symbols", "Removing symbols", "Brush and hose symbols", "Importing and exporting symbols", "Working with others"],
                 keywords: ["symbol", "instance", "library", "symbols", "document", "choose", "artwork", "team", "list", "instances", "object", "panel", "click", "part", "override", "edit", "options", "menu", "folder", "select", "copy", "name", "canvas", "same", "every", "overrides", "changes", "objects", "selected", "color", "someone", "swap", "selection", "drag", "release", "editing", "edits", "lists", "master", "preview"]),
        HelpPage(slug: "linking-embedding", title: "Linking and embedding", group: "Document setup", summary: "Images and other files you import into a document are either embedded -- stored with the document in the cloud, so everyone who opens it has them -- or linked -- kept as a reference to a file outside the document, so they can be updated from their source.  WireTuner embeds by default.  A linked file still carries a copy of its content in the document, so collaborators and other Macs always see the picture; the link is what lets you update it from the original.  The",
                 headings: ["Embedded and linked files", "The Links window", "Broken links when opening", "Working with others"],
                 keywords: ["file", "document", "linked", "copy", "link", "links", "update", "files", "source", "window", "embedded", "imported", "name", "import", "stored", "wiretuner", "content", "relinks", "choose", "image", "every", "path", "last", "unavailable", "object", "another", "same", "embed", "broken", "artwork", "library", "shows", "importing", "size", "modified", "found", "images", "cloud", "everyone", "opens"]),
        HelpPage(slug: "live-effects", title: "Live vector effects", group: "Effects", summary: "A live effect changes how an object looks without touching the object itself.  The path you drew stays exactly as you drew it; the effect is an attribute stacked on top of it, next to its strokes and fills, and you can adjust it, reorder it or remove it at any time.  WireTuner has two families of live effects.  Vector effects -- Bend, Combine, Corners, Duet, Expand Path, Ragged, Sketch and Transform -- produce new vector outlines, so they stay crisp at any zoom and on any printer.  Raster effects -- bevels, blurs, shadows, glows and sharpening -- produce pixels and are covered in Live raster effects; the Transparency effect has its own page, Transparency.  This page covers where effects live, how you manage them, and every option of the eight vector effects.",
                 headings: ["Effects in the Object panel", "Bend", "Combine", "Corners", "Duet", "Expand Path", "Ragged", "Sketch", "Transform", "Working with others"],
                 keywords: ["effect", "object", "effects", "path", "points", "stroke", "group", "shape", "centre", "corners", "panel", "outline", "point", "fill", "corner", "choose", "same", "copies", "bend", "ragged", "live", "every", "list", "combine", "expand", "change", "menu", "apply", "members", "radius", "both", "strokes", "option", "selected", "pop-up", "drawn", "center", "round", "tool", "appearance"]),
        HelpPage(slug: "master-pages", title: "Master pages", group: "Document setup", summary: "A master page is a page layout that other pages inherit: its size, orientation and bleed, plus any objects placed on it -- running heads, folios, frames, a logo.  Pages that follow a master are its",
                 headings: ["How master pages behave", "Creating a master page", "Applying a master page to pages", "Editing a master page", "Releasing a child page", "Importing and exporting master pages", "Working with others"],
                 keywords: ["master", "child", "panel", "objects", "document", "library", "choose", "select", "options", "menu", "size", "symbols", "bleed", "edit", "layer", "same", "layout", "orientation", "open", "children", "another", "ordinary", "person", "every", "icon", "following", "release", "looks", "tool", "pop-up", "selected", "sheet", "copied", "released", "follow", "editing", "updates", "needs", "templates", "starts"]),
        HelpPage(slug: "monitor-calibration", title: "Calibrating your display", group: "Color management", summary: "Your display is the one device in the color workflow that belongs to your Mac rather than to the document.  WireTuner does not calibrate it; macOS does.  Every display attached to a Mac has a ColorSync profile -- a factory one for Apple displays, a generic or manufacturer one for others, or a custom one made with a measuring device -- and WireTuner draws every window through the profile of the screen it is on.  Your job is to make sure that profile is a good one.",
                 headings: ["Seeing which profile is in use", "Calibrating with the Display Calibrator Assistant", "Calibrating with a measuring device", "Matching printed samples", "Working with others"],
                 keywords: ["profile", "display", "wiretuner", "macos", "displays", "screen", "settings", "target", "document", "colors", "print", "color", "rather", "every", "window", "choose", "click", "changes", "open", "work", "white", "device", "calibrate", "others", "calibrator", "assistant", "visual", "calibration", "monitor", "system", "match", "light", "option", "gamma", "point", "printed", "software", "printer", "proof", "nothing"]),
        HelpPage(slug: "moving", title: "Moving objects", group: "Objects", summary: "You can move a selection by dragging it, by nudging it with the arrow keys, or by typing where it should go.  While you drag, the Info toolbar reads out the distance moved and the pointer's position, and the selection snaps to points, guides, smart guides and the grid when snapping is on.",
                 headings: ["Dragging", "Nudging with the arrow keys", "Moving numerically", "Snapping", "Smart guides", "The Info toolbar", "Moving between documents", "Working with others"],
                 keywords: ["object", "guides", "snap", "move", "selection", "smart", "distance", "pointer", "position", "dragging", "point", "drag", "grid", "guide", "objects", "document", "hold", "release", "moves", "another", "option", "copies", "shows", "distances", "wiretuner", "settings", "default", "panel", "click", "view", "lines", "nearby", "arrow", "info", "moved", "snaps", "points", "horizontal", "vertical", "until"]),
        HelpPage(slug: "names-notes", title: "Naming objects and adding notes", group: "Objects", summary: "Any object can carry a name and a note.  Names make objects findable -- in the Find & Replace panel, in the Layers panel, in the Info toolbar as you point at things -- and notes hold whatever you want to say about an object to yourself or to the people you share the document with.  Both can be exported as annotations in PDF.  Next to them sits a third field, Alt text, and a Decorative checkbox: together they describe the object for people who cannot see it, and they go into every SVG, PDF and web page WireTuner writes (<<accessibility,Describing objects for accessibility>>).",
                 headings: ["Naming an object", "Notes written by WireTuner", "Describing objects for accessibility [[accessibility]]", "Working with others"],
                 keywords: ["object", "order", "name", "note", "objects", "decorative", "names", "panel", "document", "accessibility", "type", "read", "reading", "notes", "both", "writes", "same", "shows", "group", "screen", "reader", "sheet", "find", "people", "field", "describe", "root", "exporting", "move", "later", "replace", "layers", "info", "every", "selected", "open", "select", "characters", "nothing", "lists"]),
        HelpPage(slug: "object-panel", title: "Using the Object panel", group: "Objects", summary: "The Object panel is WireTuner's inspector.  Whatever is selected -- a path, a text block, a group, a bitmap, twelve objects of mixed kinds, or nothing at all -- the panel shows what it is and lets you change it.  Almost every drawing task passes through it: strokes and fills are added here, effects are stacked here, a rectangle's corner radius and a blend's step count are typed here.  The panel is docked in the Properties group by default; show or hide it with Window Object (Cmd+F3).",
                 headings: ["Layout", "Editing values", "Properties by kind", "Mixed selections", "With nothing selected", "Working with others"],
                 keywords: ["object", "selected", "attributes", "shows", "every", "fill", "value", "stroke", "panel", "properties", "list", "size", "document", "root", "position", "field", "path", "objects", "corner", "effect", "same", "name", "above", "effects", "show", "drawn", "type", "attribute", "unit", "changes", "group", "radius", "contents", "note", "press", "point", "typing", "values", "block", "change"]),
        HelpPage(slug: "opentype-features", title: "OpenType features", group: "Typeface documents", summary: "OpenType features are the rules inside a font that go beyond one character, one glyph: kerning, accents that attach to letters, f and i becoming a ligature, small capitals, alternate figures.  WireTuner generates the common features for you from what you have already drawn -- kerning from the Metrics window, mark attachment from anchors, ligatures from glyph names",
                 headings: ["Features generated automatically", "The Features editor", "Previewing substitutions", "Working with others"],
                 keywords: ["feature", "features", "glyph", "font", "file", "editor", "generated", "every", "kerning", "classes", "figures", "mark", "ligature", "metrics", "window", "names", "syntax", "liga", "kern", "class", "same", "type", "name", "glyphs", "both", "suffix", "generate", "shows", "check", "character", "written", "pane", "document", "editing", "pair", "base", "anchor", "rule", "whose", "kind"]),
        HelpPage(slug: "output-area", title: "Defining an output area", group: "Printing", summary: "An output area is a rectangle you draw over the pasteboard to say \"print or export this\".  It can cover part of one page, several whole pages and the pasteboard between them, or objects parked beside a page.  A document has one output area at a time; it is saved with the document, shared with everyone working in it, and used by the Print dialog's Output area choice and by the export dialogs.  Its typical uses are ganging several small pages -- business cards, labels -- onto one sheet, and cutting a proof down to the corner that matters.",
                 headings: ["Defining an output area", "Adjusting an output area", "Printing and exporting the area", "Working with others"],
                 keywords: ["area", "output", "print", "drag", "rectangle", "tool", "panel", "pasteboard", "export", "document", "object", "choice", "pointer", "include", "view", "shift", "option", "dashed", "handle", "active", "remove", "choose", "same", "several", "objects", "beside", "everyone", "working", "dialog", "dialogs", "small", "sheet", "corner", "handles", "select", "becomes", "visible", "hold", "centre", "drawn"]),
        HelpPage(slug: "output-devices", title: "Choosing an output device", group: "Printing", summary: "Where a document is going to be printed decides how to print it.  A desktop inkjet or laser printer wants a composite job through its own driver, color-managed by ColorSync, and gets it with no settings at all.  A commercial press wants separated, marked, bled plates -- or, more often today, a PDF the shop's prepress system will separate itself.  This page explains what WireTuner sends to each kind of device, which options matter for which, and how to get a job to a service provider.",
                 headings: ["Desktop printers and proofs", "High-resolution output and separations", "Working with a service provider", "Working with others"],
                 keywords: ["printer", "print", "wiretuner", "shop", "document", "plate", "colors", "screen", "plates", "choose", "itself", "file", "every", "spot", "composite", "device", "separations", "resolution", "screens", "marks", "fonts", "wants", "prepress", "pane", "paper", "process", "prints", "select", "output", "imaging", "printing", "bleed", "dialog", "save", "list", "halftones", "printed", "desktop", "colorsync", "settings"]),
        HelpPage(slug: "pages", title: "Working with pages", group: "Document setup", summary: "A WireTuner document has one or more pages laid out on a single large pasteboard.  Pages can be any size, can differ from one another, and can sit anywhere on the pasteboard; objects can be placed on a page, on the pasteboard between pages, or across a page edge.  You add, duplicate, remove, resize and move pages with the Page tool on the canvas or with the Document panel (The Document panel).  Every page change is part of the document and syncs to everyone.",
                 headings: ["Adding pages", "Selecting pages", "Duplicating, removing and moving pages", "Page order", "Modifying, resizing and rotating pages", "Working with others"],
                 keywords: ["document", "pasteboard", "tool", "panel", "objects", "choose", "master", "drag", "click", "active", "both", "move", "select", "view", "grid", "size", "resize", "order", "sheet", "number", "hold", "snap", "remove", "change", "selected", "handles", "bottom", "window", "settings", "options", "menu", "following", "removed", "keep", "dragging", "person", "wiretuner", "duplicate", "button", "orientation"]),
        HelpPage(slug: "panels", title: "Using panels", group: "Basics", summary: "Panels are the small windows that show and change what is selected: the Object panel for an object's properties, Swatches for colors, Layers for stacking, and so on.  They live in",
                 headings: ["The default layout", "Opening, closing and activating panels", "Docking and floating", "Grouping panels", "The Options menu", "Panel layouts", "Panel appearance", "The panels", "Working with others"],
                 keywords: ["panel", "group", "groups", "panels", "edge", "drag", "window", "document", "cluster", "dock", "floating", "docked", "title", "tabs", "shows", "click", "properties", "menu", "object", "show", "layers", "float", "find", "replace", "name", "choose", "every", "move", "help", "column", "options", "left", "assets", "mixer", "tints", "strip", "swatches", "tools", "layout", "select"]),
        HelpPage(slug: "paragraphs", title: "Paragraphs", group: "Type", summary: "A paragraph is everything between two Returns, and the settings on this page belong to paragraphs rather than characters: how lines align, how far apart paragraphs sit, whether words may be hyphenated, whether a rule is drawn beneath, and how a paragraph may be split between columns.  Set them for the paragraph holding the insertion point, for every paragraph in a Text tool selection, or for every paragraph in blocks selected with the Pointer tool. Most live in the Paragraph and Spacing sections of the Object panel (The type adjustment tools); indents and tabs are on Tabs, indents and margins.",
                 headings: ["Alignment", "Paragraph spacing", "Hyphenation", "Paragraph rules", "Word and letter spacing", "Keeping lines and words together", "Hanging punctuation", "Working with others"],
                 keywords: ["paragraph", "line", "paragraphs", "spacing", "rule", "tool", "section", "column", "block", "same", "lines", "justified", "last", "width", "space", "rules", "every", "sheet", "word", "setting", "words", "above", "hyphenation", "settings", "selected", "choose", "shift", "edit", "percentage", "never", "below", "first", "hyphenate", "select", "language", "document", "stroke", "characters", "drawn", "blocks"]),
        HelpPage(slug: "path-effects", title: "Path-shaping tools and operations", group: "Effects", summary: "The tools and commands on this page reshape objects for good.  Where a live effect (Live vector effects) is an attribute you can adjust or remove later, everything here changes the path itself: Roughen moves the points, the Shadow tool makes a real copy behind the object, Emboss builds real facets, the 3D Rotation tool rewrites the outline.  That is the point of them -- the result is ordinary paths you can edit point by point",
                 headings: ["Adding points", "Roughening", "Fisheye lens", "Bending and bloating", "Smudging", "Adding a drop shadow with the Shadow tool", "Embossing", "Fractalize", "Mirror", "3D rotation", "Envelopes", "Working with others"],
                 keywords: ["tool", "envelope", "object", "shadow", "choose", "click", "path", "points", "edge", "point", "drag", "select", "apply", "color", "pop-up", "roughen", "emboss", "paths", "options", "copy", "lens", "soft", "objects", "live", "toolbar", "smudge", "tools", "effect", "every", "release", "rotation", "double-click", "around", "centre", "selected", "modify", "bend", "mirror", "shape", "selection"]),
        HelpPage(slug: "pen-bezigon", title: "Drawing with the Pen and Bezigon tools", group: "Drawing", summary: "The Pen and Bezigon tools build a path one point at a time, which gives you exact control over every segment.  They share a slot in the Tools panel and produce identical paths; the difference is in the hand motion.  With the Pen, you click for a corner and drag for a curve, pulling out the handles as you go, and the tool shows a preview of the segment about to be placed.  With the Bezigon, you click to drop each point and let WireTuner choose the handles, so it is the faster way to place straight segments and rough out a curve you will tune later.  Both pointers change shape to tell you what a click will do: start a path, add a point, close the path, or continue an existing one.",
                 headings: ["Drawing with the Pen tool", "Drawing with the Bezigon tool", "Continuing, closing and opening paths", "Working with others"],
                 keywords: ["point", "path", "segment", "tool", "click", "place", "bezigon", "paths", "handles", "points", "drag", "curve", "pointer", "choose", "open", "close", "dragging", "corner", "shows", "start", "continue", "ends", "turn", "selected", "closed", "tools", "panel", "preview", "placed", "segments", "both", "draw", "connector", "placing", "handle", "finish", "last", "first", "move", "editing"]),
        HelpPage(slug: "perspective", title: "Perspective grids", group: "Effects", summary: "A perspective grid is a non-printing scaffold of vanishing points, a horizon and gridded planes",
                 headings: ["Showing the grid", "Attaching objects to the grid", "Defining grids", "Working with others"],
                 keywords: ["grid", "perspective", "object", "vanishing", "arrow", "tool", "point", "floor", "wall", "horizon", "grids", "plane", "objects", "left", "view", "right", "move", "choose", "press", "button", "down", "click", "line", "points", "attached", "show", "change", "release", "define", "keep", "stays", "document", "same", "hide", "drag", "select", "mouse", "puts", "every", "pointer"]),
        HelpPage(slug: "polygons-stars", title: "Polygons and stars", group: "Drawing", summary: "The Polygon tool draws regular polygons -- triangles, pentagons, hexagons, anything up to 360 sides -- and stars.  Like rectangles and ellipses, a polygon stays a live shape: its number of sides, its star points and its proportions can be changed after drawing, by dragging handles with the Subselect tool or by typing in the Object panel.  Every polygon is a closed path, drawn clockwise from its center.",
                 headings: ["Setting the Polygon tool options", "Drawing a polygon or star", "Editing a polygon or star", "Working with others"],
                 keywords: ["polygon", "star", "tool", "points", "sides", "center", "stars", "dragging", "radius", "drag", "draws", "shape", "number", "every", "inner", "same", "subselect", "circle", "vertex", "handle", "polygons", "handles", "panel", "path", "tools", "change", "draw", "point", "choose", "rotation", "diamond", "valley", "regular", "rectangles", "live", "object", "sheet", "preview", "click", "option"]),
        HelpPage(slug: "preferences", title: "Preferences", group: "Basics", summary: "Preferences shape how WireTuner behaves for you: how close you must click to select, whether new text blocks grow as you type, which colors guides use, how much you want to be asked when your offline work meets someone else's.  Most preferences follow you from Mac to Mac through your account; a few describe the machine you are sitting at and stay there.  This page lists every preference by category.",
                 headings: ["The Preferences window", "General (synced)", "Object (synced)", "Text (synced)", "Document (synced unless noted)", "Import (synced unless noted)", "Export (synced unless noted)", "Spelling (synced)", "Colors (synced unless noted)", "Panels (local)", "Redraw (local)", "Sounds (local)", "Sync and collaboration (synced unless noted)", "Automation (synced unless noted)", "Printing (synced)", "Typeface (synced)", "Working with others"],
                 keywords: ["default", "color", "document", "local", "preference", "show", "objects", "effect", "cols", "paths", "draws", "import", "wiretuner", "guides", "panel", "editing", "preferences", "object", "view", "preview", "open", "changes", "snap", "grid", "layer", "shows", "name", "image", "formats", "exporting", "colors", "category", "tool", "selection", "resolution", "path", "point", "guide", "others", "smart"]),
        HelpPage(slug: "presence", title: "Presence: who is here and what they are doing", group: "Collaboration", summary: "Presence is everything WireTuner shows you about the other people in a document right now: who is here, where they are looking, what they have selected, where they are typing.  None of it is part of the document -- it is not saved, not in history, and it vanishes when a person closes the window.  Its purpose is to make working together feel like sharing a table rather than mailing files: you can see a colleague reaching for the object you were about to move, and you can bring everyone to the page you are talking about.  xref:collaboration.adoc[Working together] is the overview; this page has the details and the options.",
                 headings: ["The avatar strip", "Colors", "Cursors", "Selections and carets", "Following someone", "Asking others to follow you", "Display options", "Presence and the network", "Working with others"],
                 keywords: ["document", "avatar", "following", "selection", "people", "object", "collaborators", "name", "color", "view", "cursor", "person", "editing", "everyone", "follow", "choose", "selected", "working", "shown", "branch", "click", "stop", "else", "collaborator", "shows", "spotlight", "caret", "pointer", "cursors", "same", "show", "presence", "strip", "card", "open", "nothing", "seconds", "priya", "stays", "canvas"]),
        HelpPage(slug: "print-fonts", title: "Printing fonts", group: "Printing", summary: "Text prints with the fonts it is set in.  On a modern Mac that is nearly the whole story: the fonts installed on your Mac -- OpenType, TrueType, and the older PostScript Type 1 where macOS still loads them -- are embedded in the print job automatically, so any printer receives the exact glyphs you see.  This page covers the cases that need attention: fonts the document uses but your Mac lacks, fonts whose license forbids embedding, and the option of turning text into outlines for a difficult printer.",
                 headings: ["How fonts reach the printer", "Missing fonts", "Fonts that will not embed", "Font formats on macOS", "Working with others"],
                 keywords: ["fonts", "font", "print", "prints", "printer", "wiretuner", "substitute", "printing", "still", "document", "opentype", "macos", "outlines", "same", "every", "substitution", "missing", "installed", "type", "license", "printed", "warning", "collaborator", "paths", "truetype", "postscript", "loads", "embedded", "glyphs", "whose", "forbids", "embedding", "sheet", "layout", "path", "small", "pane", "click", "open", "choose"]),
        HelpPage(slug: "print-performance", title: "Faster printing", group: "Printing", summary: "WireTuner draws a printed page the way it draws the canvas, so a document that is quick to redraw is quick to print, and a document that is slow on screen will be slow to spool.  The printer then has its own limits: memory, and the speed of its interpreter on a complex page. This page collects what to do about both, and describes the progress panel that lets a long job be watched or cancelled.",
                 headings: ["Drawing for fast output", "Options for difficult printers", "Watching and cancelling a job", "Working with others"],
                 keywords: ["document", "printer", "print", "prints", "resolution", "wiretuner", "complex", "panel", "fewer", "path", "draws", "slow", "objects", "printing", "points", "drawn", "paths", "flatness", "effects", "raster", "bitmaps", "image", "sheet", "printed", "quick", "memory", "both", "progress", "lets", "cancelled", "keep", "hidden", "cleanup", "everything", "layer", "background", "never", "simplify", "curves", "straight"]),
        HelpPage(slug: "print-preview", title: "Print preview", group: "Printing", summary: "The Print dialog shows, on its left, a preview of every sheet the job will produce, drawn with the settings currently chosen.  Change the scale, turn on tiling, switch to separations or add crop marks, and the preview redraws.  It is the place to check that a page fits the paper, that marks are not being clipped, and that a tiled poster comes out as the number of sheets you expect -- before any paper is used.",
                 headings: ["Reading the preview", "Positioning the page on the paper", "Previewing at full size", "Working with others"],
                 keywords: ["preview", "paper", "print", "sheet", "dialog", "offset", "bleed", "area", "document", "marks", "moves", "every", "chosen", "tiling", "grid", "prints", "printer", "someone", "changes", "shows", "drawn", "separations", "crop", "redraws", "clipped", "sheets", "tile", "artwork", "edge", "outline", "appears", "output", "band", "shown", "move", "wiretuner", "values", "click", "return", "nothing"]),
        HelpPage(slug: "printing", title: "Printing a document", group: "Printing", summary: "Printing in WireTuner goes through the standard macOS Print dialog.  The dialog's own panes handle the printer, paper, copies and page range; a WireTuner pane added to it handles everything an illustration needs beyond that: which pages or which area to print, scaling and tiling, composite or separated output, printer's marks, bleed and the per-ink settings a prepress shop asks for.  Nothing in the print path leaves your Mac -- the same drawing code that paints the canvas paints the printed page, so what you see is what prints.",
                 headings: ["The Print dialog", "Choosing what to print", "Scaling", "Tiling", "Composite or separations", "Trapping", "Printer's marks, bleed and labels", "Imaging options", "Color management", "Working with others"],
                 keywords: ["print", "output", "document", "printer", "paper", "every", "dialog", "marks", "area", "prints", "plate", "color", "trap", "bleed", "wiretuner", "sheet", "objects", "layers", "edge", "object", "pane", "panel", "options", "separations", "cols", "printing", "composite", "choose", "size", "artwork", "spot", "process", "lighter", "tiling", "settings", "printed", "selected", "click", "tile", "colors"]),
        HelpPage(slug: "publish-html", title: "Publishing as HTML", group: "Web and animation", summary: "(or PNG) per page, the images, fonts and video the pages need, and a stylesheet.  Open the folder in a browser and the document is there, links working, animation playing, at any screen size.  You can publish to a folder on your Mac, or publish to a web link -- a read-only copy hosted for you that anyone with the link can open, updated each time you publish again.",
                 headings: ["Publishing", "HTML settings", "Publishing to a web link", "Working with others"],
                 keywords: ["publish", "document", "html", "folder", "link", "sheet", "setting", "same", "choose", "fonts", "default", "output", "browser", "links", "click", "writes", "setup", "font", "files", "animation", "edit", "publishing", "placed", "animations", "option", "open", "settings", "file", "warnings", "every", "objects", "published", "colors", "address", "index", "images", "again", "named", "wiretuner", "list"]),
        HelpPage(slug: "raster-effects", title: "Live raster effects", group: "Effects", summary: "Raster effects give a vector object the kinds of treatment a photo editor gives a picture: a beveled or embossed edge, a blur, a drop shadow or glow, a sharpened edge.  They are live effects like the vector ones on Live vector effects -- attributes in the Object panel's appearance list that never alter the path -- but their result is made of pixels.  WireTuner draws them at a raster effects resolution you set for the document (or for one object), so they look right on the device they are meant for and print at that resolution. This page covers the resolution settings, the preview quality preference, each raster effect and every one of its options, and what happens to raster effects on the way to a printer or an exported file.  Transparency is a raster-family effect with its own page, Transparency.",
                 headings: ["Resolution", "Bevel and Emboss", "Blur", "Shadow and Glow", "Sharpen", "Raster effects and color", "Printing and exporting raster effects", "Working with others"],
                 keywords: ["object", "raster", "effects", "effect", "resolution", "shadow", "document", "color", "bevel", "glow", "inner", "vector", "screen", "emboss", "edge", "blur", "choose", "click", "fill", "drop", "pixels", "preview", "options", "cmyk", "print", "drawn", "bitmap", "apply", "width", "sharpen", "panel", "settings", "export", "setting", "same", "raised", "inside", "value", "live", "look"]),
        HelpPage(slug: "rasterizing", title: "Rasterizing vector artwork", group: "Imported artwork", summary: "Rasterizing turns vector objects into a bitmap image inside the document.  You might do it to flatten a complex effect that prints slowly, to make a pixel version of a logo for an image editor, to freeze the look of something so nobody can nudge it, or simply because a screen graphic only needs pixels.  The result is an ordinary image object that behaves like an imported one (Working with bitmap images).",
                 headings: ["Rasterizing selected objects", "Working with others"],
                 keywords: ["image", "objects", "resolution", "result", "object", "rasterize", "images", "effects", "size", "default", "rasterizing", "pixel", "pixels", "rasterized", "live", "selection", "name", "bitmap", "might", "effect", "something", "screen", "imported", "paths", "options", "none", "edges", "transparent", "shows", "grayscale", "panel", "keep", "originals", "selected", "exactly", "strokes", "first", "everything", "cannot", "copy"]),
        HelpPage(slug: "rectangles-ellipses-lines", title: "Rectangles, ellipses and lines", group: "Drawing", summary: "Rectangles, ellipses and lines are the shapes you draw most, so WireTuner gives each its own tool and makes the first two live shapes: a rectangle remembers that it is a rectangle, so you can round its corners or retype its size in the Object panel long after drawing it.  A line is an ordinary two-point path.  The three tools share one slot in the Tools panel; press and hold the slot to pick one.",
                 headings: ["Drawing a rectangle, ellipse or line", "Rectangles with rounded corners", "Editing a shape by numbers", "Arcs", "Converting a shape to a path", "Working with others"],
                 keywords: ["rectangle", "shape", "radius", "corners", "corner", "ellipse", "tool", "panel", "draw", "object", "drag", "angle", "path", "round", "size", "line", "tools", "type", "uniform", "rectangles", "live", "choose", "center", "stays", "shift", "default", "four", "effect", "position", "arcs", "both", "ellipses", "release", "instead", "option", "dragging", "becomes", "constrain", "every", "drawn"]),
        HelpPage(slug: "rulers", title: "Rulers and units", group: "Document setup", summary: "Page rulers run along the top and left edges of the document window and measure the pasteboard in the document's units.  They follow the view as you scroll and zoom, show the pointer's position as you move it, and are the place you drag guides from (Grid and guides). The point they count from -- the zero point -- can be moved, and each page remembers its own.",
                 headings: ["Showing and hiding the rulers", "The zero point", "Coordinates in the Info bar", "Custom units", "Working with others"],
                 keywords: ["unit", "rulers", "units", "document", "point", "zero", "custom", "active", "same", "window", "view", "move", "choose", "panel", "edit", "define", "left", "show", "position", "drag", "guides", "showing", "zero-point", "marker", "object", "info", "built-in", "pop-up", "sheet", "click", "name", "type", "time", "edges", "pasteboard", "follow", "zoom", "pointer", "grid", "count"]),
        HelpPage(slug: "saving", title: "Saving", group: "Saving and exporting", summary: "WireTuner has no Save command that talks to the network.  Every change you make is on screen the instant you make it, written to this Mac within a quarter of a second, and sent to the cloud as soon as there is a connection.  A crash, a dead battery or a closed lid loses at most that last quarter second, and you never have to remember to save.  What the File menu offers instead is a set of commands about versions and copies: bookmarking a moment in the document's history, duplicating the document, exporting a self-contained package for backup or exchange, and restoring an earlier version.",
                 headings: ["The sync indicator", "Saving a version", "Duplicating a document", "Restoring a version", "Packages: a document as a file", "Keeping a copy on this Mac", "Quick Look and Spotlight", "The same document on two of your Macs", "Closing and quitting with changes waiting", "Storage [[storage]]", "Working with others"],
                 keywords: ["document", "changes", "package", "version", "cloud", "wiretuner", "same", "copy", "file", "history", "offline", "window", "open", "every", "shows", "images", "waiting", "save", "state", "nothing", "documents", "sync", "indicator", "versions", "storage", "export", "name", "second", "named", "uploading", "until", "choose", "full", "opens", "restore", "change", "never", "note", "title", "reached"]),
        HelpPage(slug: "scripting", title: "Scripting and automation", group: "Automation and data", summary: "WireTuner can be driven by scripts in three ways: by AppleScript through Script Editor, by Shortcuts and Automator-style workflows through App Intents, and by JavaScript scripts written in WireTuner's own Script Editor panel and run from its Scripts menu.  All three expose the same things -- documents, pages, master pages, layers, the objects on them and their properties, export and printing -- and all three produce ordinary document changes that sync and are undoable like anything done by hand.  JavaScript goes further: it can fetch data from the web (through the WireTuner cloud), drive a data merge (Data merge) and show its own small dialogs.  The scripting surface in version 1 is deliberately small; it grows with the features that ship.",
                 headings: ["AppleScript", "Shortcuts and App Intents", "JavaScript", "Working with others"],
                 keywords: ["script", "document", "scripts", "editor", "open", "wiretuner", "name", "library", "data", "merge", "javascript", "runs", "panel", "same", "documents", "change", "options", "team", "export", "layer", "size", "edit", "object", "shortcuts", "objects", "changes", "fetch", "choose", "file", "print", "block", "find", "folder", "every", "console", "records", "progress", "menu", "master", "cloud"]),
        HelpPage(slug: "selecting", title: "Selecting objects", group: "Objects", summary: "Before you can move, color or transform anything you select it.  WireTuner selects with three tools -- Pointer, Subselect and Lasso -- with the keyboard, and with the Edit Select commands.  Selection is yours alone: it is never saved with the document, and what you have selected is visible to collaborators only as a colored outline with your name.",
                 headings: ["The selection tools", "Selection commands", "Selecting inside groups and other containers", "Selecting through stacked objects", "What cannot be selected", "Working with others"],
                 keywords: ["object", "click", "selected", "selection", "select", "objects", "pointer", "edit", "tool", "same", "subselect", "selects", "path", "group", "hold", "every", "points", "marquee", "inside", "fill", "option", "stroke", "color", "document", "member", "container", "point", "lasso", "panel", "hidden", "never", "clicking", "selecting", "another", "shift", "command", "current", "wiretuner", "tools", "visible"]),
        HelpPage(slug: "sharing", title: "Sharing documents, teams and roles", group: "Collaboration", summary: "A document lives in one space: your personal space, or a team you belong to.  Who can open it, and what they may do with it, is decided by the roles you give people and links in the Share sheet, and -- for a team document -- by the team's default.  This page covers the Share sheet, roles, links, teams and team libraries, and what happens to someone whose access changes while they are working.  Accounts and teams themselves (signing in, creating a team, company workspaces) are described briefly here and in full in Accounts, teams and security.",
                 headings: ["Signing in", "Spaces: Personal and teams", "Roles", "The Share sheet", "Share links", "Access for the whole team", "Requesting access", "Transferring ownership", "When your access changes mid-session", "Team libraries", "Working with others"],
                 keywords: ["team", "document", "library", "role", "link", "access", "people", "share", "sheet", "open", "owner", "change", "name", "default", "choose", "copy", "links", "teams", "email", "same", "remove", "never", "space", "personal", "changes", "popup", "invite", "every", "viewer", "person", "offline", "list", "company", "address", "editor", "click", "once", "workspace", "account", "documents"]),
        HelpPage(slug: "spirals-arcs", title: "Spirals and arcs", group: "Drawing", summary: "The Spiral and Arc tools draw two shapes that are tedious to build by hand: a spiral with evenly spaced or steadily widening turns, and a quarter-circle arc, open or closed into a wedge.  Both tools share the Tools panel slot with the Polygon tool.  Unlike rectangles and polygons, a spiral or arc is an ordinary path as soon as you release the mouse: every point is yours to edit, and the tool settings only decide how it is generated.",
                 headings: ["Spirals", "Arcs", "Working with others"],
                 keywords: ["spiral", "tool", "drag", "draw", "closed", "path", "center", "tools", "open", "turn", "draws", "curve", "release", "every", "options", "option", "setting", "points", "turns", "panel", "point", "sheet", "expanding", "press", "outer", "corner", "direction", "outward", "keys", "dragging", "create", "flipped", "concave", "regardless", "wedge", "ordinary", "edit", "settings", "double-click", "click"]),
        HelpPage(slug: "spot-process", title: "Spot and process colors, color spaces and libraries", group: "Color", summary: "Every color in a WireTuner document is two things at once: a value in some color space (how much cyan, or how much red) and a kind of ink -- spot or process -- that only matters when the document is separated for a press.  This page explains both, how to convert between them, and the color libraries that supply ready-made, press-matched colors.",
                 headings: ["Spot and process colors", "Color spaces", "Color libraries", "Working with others"],
                 keywords: ["color", "colors", "space", "process", "library", "srgb", "swatch", "display", "cmyk", "spot", "document", "every", "value", "libraries", "panel", "same", "name", "wiretuner", "press", "convert", "swatches", "stored", "kind", "plate", "black", "screen", "choose", "oklch", "show", "mixed", "shows", "converting", "change", "options", "menu", "default", "numbers", "opens", "another", "mixer"]),
        HelpPage(slug: "stroke-attributes", title: "Strokes", group: "Strokes and fills", summary: "A stroke is a line drawn along an object's path.  WireTuner offers five kinds of stroke, chosen from the Stroke type pop-up at the top of the stroke editor in the Object panel: Basic (a plain line with caps, joins, dashes and arrowheads), Brush (symbols painted or sprayed along the path), Calligraphic (a pen nib dragged along the path), Custom (one of twenty-three repeating ornamental patterns) and Pattern (an editable bitmap pattern).  Select the stroke in the Attributes list (xref:attribute-stack.adoc[Strokes, fills and the Attributes list]) and the editor below shows the options for its kind.  Colors are chosen as described in Applying color.",
                 headings: ["Stroke width presets", "Basic strokes", "Brush strokes", "Calligraphic strokes", "Custom strokes", "Pattern strokes", "Working with others"],
                 keywords: ["stroke", "brush", "path", "pop-up", "choose", "width", "dash", "along", "pattern", "custom", "edit", "selected", "arrowhead", "editor", "type", "arrowheads", "color", "symbol", "copy", "line", "calligraphic", "strokes", "change", "point", "click", "chosen", "list", "object", "dashes", "symbols", "apply", "every", "paint", "library", "random", "drawn", "panel", "basic", "patterns", "shows"]),
        HelpPage(slug: "styles", title: "Using styles", group: "Layers, symbols and styles", summary: "A style is a named set of attributes you apply in one click and change in one place.",
                 headings: ["The Styles panel", "Applying styles", "Adding, duplicating and removing styles", "Modifying and redefining styles", "Basing one style on another", "Copying styles between documents", "Working with others"],
