        HelpPage(slug: "svg-animation", title: "SVG animations and browser preview", group: "Web and animation", summary: "WireTuner imports animations, places them on a page, sends them out for editing, exports the document as an animation, and tests the result in a browser.  It does each of those jobs with",
                 headings: ["Placing an SVG animation", "Preview in Browser", "Working with others"],
                 keywords: ["animation", "file", "browser", "preview", "placed", "document", "frame", "object", "animations", "size", "poster", "html", "still", "choose", "published", "links", "default", "animated", "time", "output", "panel", "play", "keeps", "image", "sheet", "scripts", "drag", "wiretuner", "exports", "every", "canvas", "current", "playing", "export", "position", "import", "first", "itself", "selected", "setting"]),
        HelpPage(slug: "swatches", title: "Using the Swatches panel", group: "Color", summary: "The Swatches panel is the document's color list.  Every color you name lives here, and a color that lives here is named: apply it to fifty objects, then edit the swatch, and all fifty change.  The panel also converts colors between spot and process and between color spaces, imports color libraries, exports your own, and tidies the list.  Show or hide it with Window Swatches.",
                 headings: ["The panel", "Adding colors", "Managing the list", "Removing colors", "Importing Photoshop color tables", "Working with others"],
                 keywords: ["color", "colors", "name", "panel", "swatch", "swatches", "list", "object", "choose", "named", "names", "objects", "process", "mixer", "spot", "fill", "stroke", "tints", "every", "menu", "show", "default", "click", "drag", "remove", "group", "document", "options", "sheet", "unnamed", "tint", "both", "selected", "drop", "keep", "srgb", "extensions", "removed", "press", "select"]),
        HelpPage(slug: "tabs-indents", title: "Tabs, indents and margins", group: "Type", summary: "Tabs, indents and margins are how you line things up inside a text block: columns of figures, hanging bullets, a quotation pulled in from both sides, a caption set a few points in from the block's edge.  Tabs and indents belong to paragraphs and are set on the text ruler above a block or in the Paragraph section of the Object panel; margins (insets) belong to the block and are set in its Text Block section.",
                 headings: ["The text ruler", "Setting tabs", "Indents", "Margins (insets)", "Working with others"],
                 keywords: ["paragraph", "indent", "left", "block", "stop", "tabs", "ruler", "line", "right", "indents", "drag", "edge", "paragraphs", "both", "points", "section", "click", "type", "first", "hanging", "above", "object", "panel", "markers", "default", "every", "wrapping", "move", "leader", "negative", "values", "belong", "tool", "well", "next", "center", "decimal", "below", "edit", "sheet"]),
        HelpPage(slug: "templates", title: "Templates and starting points", group: "Document setup", summary: "A template is a document you start other documents from.  It carries everything a document can: pages and their sizes, master pages, guides, layers, graphic and text styles, swatches, symbols, brushes, custom page sizes and custom units, and any objects you leave on the pages.  Templates live in your library like any other document, marked with a template badge, and appear in the",
                 headings: ["Starting a document from a template", "Saving a document as a template", "The default template", "What a template carries", "Working with others"],
                 keywords: ["template", "document", "templates", "custom", "library", "file", "choose", "default", "team", "settings", "documents", "guides", "units", "objects", "gallery", "built-in", "window", "everything", "sizes", "master", "styles", "swatches", "starting", "wiretuner", "copy", "start", "layers", "graphic", "symbols", "brushes", "points", "create", "opens", "open", "turn", "print", "publication", "technical", "grid", "click"]),
        HelpPage(slug: "text-blocks", title: "Working with text blocks", group: "Type", summary: "Once a text block exists it is an object like any other: select it with the Pointer tool, drag it, delete it, group it, put it on a layer, rotate or skew it, give it a stroke and a fill.  This page covers what is particular to text blocks -- their handles, the link box in their corner, switching between fixed and auto-expanding, insets, and flowing one story through several blocks.  Creating a block is on Creating text; what goes on inside it starts at Editing text.",
                 headings: ["Reading the handles", "Moving, resizing and deleting", "Fixed-size or auto-expanding", "The Text Block section of the Object panel", "Double-click behaviors", "Linking text blocks", "Working with others"],
                 keywords: ["block", "link", "auto-expanding", "handle", "overflow", "fixed", "width", "blocks", "height", "select", "handles", "shows", "path", "tool", "drag", "side", "chain", "pointer", "size", "empty", "dimension", "auto", "object", "corner", "line", "fixed-size", "choose", "type", "both", "once", "delete", "editing", "bottom", "center", "another", "double-click", "panel", "flows", "same", "stroke"]),
        HelpPage(slug: "text-color", title: "Coloring text and text blocks", group: "Type", summary: "Text has two things you can color: the characters and the block that holds them.  Characters take a fill (the glyph itself) and, if you like, a stroke (an outline around each glyph).  The block takes a stroke and a fill of its own, drawn as a rectangle behind the text.  Both are set in the Object panel, and both accept a color dragged straight from the Swatches panel or the Color Mixer.  Everything about choosing and mixing color is on Applying color; this page is what is specific to text.",
                 headings: ["Coloring characters", "Coloring the block", "Dropping color on text", "Working with others"],
                 keywords: ["color", "block", "fill", "stroke", "characters", "panel", "swatches", "select", "tool", "drop", "glyph", "well", "click", "border", "object", "mixer", "range", "pointer", "properties", "list", "sub-row", "shows", "selected", "attributes", "colors", "above", "rules", "take", "itself", "outline", "around", "both", "drag", "onto", "choose", "appears", "settings", "xref", "stroke-attributes", "adoc"]),
        HelpPage(slug: "text-effects", title: "Text effects, inline graphics and text wrap", group: "Type", summary: "Beyond fonts and colors, text can carry six built-in effects -- highlight, inline, shadow, strikethrough, underline and zoom -- each with its own options; it can hold inline graphics, objects pasted into the text that flow with it like characters; other text can",
                 headings: ["Text effects", "Inline graphics", "Wrapping text around objects", "Vertical text", "Working with others"],
                 keywords: ["effect", "object", "graphic", "inline", "color", "around", "block", "select", "choose", "characters", "edit", "click", "options", "effects", "shadow", "wrap", "path", "highlight", "tool", "copy", "strikethrough", "underline", "zoom", "inside", "paths", "character", "pop-up", "cols", "option", "meaning", "line", "band", "stroke", "width", "offset", "size", "find", "flow", "apply", "bottom"]),
        HelpPage(slug: "text-on-path", title: "Text on a path", group: "Type", summary: "Text does not have to sit in a rectangle.  Attach a text block to a path and the characters follow its curve -- around a circle, along a wave, up a diagonal.  Flow text inside a closed path and it fills the shape, wrapping at the path's edges.  Either way the text stays text: you can edit it, style it, spell-check it, and link it to other blocks; and the path stays a path you can reshape.  Text wrap around objects is on xref:text-effects.adoc[Text effects, inline graphics and text wrap].",
                 headings: ["Attaching text to a path", "Orientation and alignment on the path", "Flowing text inside a path", "Detaching", "Working with others"],
                 keywords: ["path", "block", "along", "tool", "curve", "select", "bottom", "pointer", "attach", "closed", "link", "choose", "click", "glyphs", "left", "right", "flow", "inside", "shape", "runs", "object", "follow", "around", "circle", "stays", "edit", "direction", "type", "paragraph", "overflow", "alignment", "panel", "reverse", "vertical", "stay", "attaching", "same", "triangle", "characters", "edges"]),
        HelpPage(slug: "text-styles", title: "Text styles", group: "Type", summary: "A text style is a named set of type settings -- font, size, leading, alignment, indents, tabs, rules, effects, color, variable-font axes and OpenType features -- that you apply to paragraphs with one click and change everywhere at once by editing the style.  Styles live in the Styles panel (Window Styles) alongside the graphic styles for paths; this page covers the text side.  The panel itself, importing and exporting styles, and graphic styles are on Styles.",
                 headings: ["Creating a text style", "Editing a style", "Style behavior", "Applying a style", "Overrides", "Removing a style", "Working with others"],
                 keywords: ["style", "styles", "paragraph", "settings", "panel", "click", "choose", "character", "select", "selected", "every", "setting", "name", "tool", "selection", "font", "change", "block", "options", "parent", "shows", "pop-up", "rules", "once", "document", "override", "sheet", "same", "type", "size", "leading", "alignment", "effects", "color", "axes", "apply", "graphic", "normal", "range", "based"]),
        HelpPage(slug: "text-to-paths", title: "Converting text to paths", group: "Type", summary: "Converting text to paths turns each character into an ordinary vector shape.  Once converted you can reshape letters point by point, use a word as a clipping path, give it gradient and pattern fills, run it through path effects, and send the file anywhere without worrying about fonts.  What you give up is the text: it is no longer editable as words, its spelling and formatting are frozen, and it no longer follows a text style.",
                 headings: ["Converting", "Going back", "Working with others"],
                 keywords: ["paths", "path", "fonts", "group", "block", "font", "character", "convert", "becomes", "history", "converting", "converted", "letters", "longer", "blocks", "first", "fill", "stroke", "back", "undo", "turns", "vector", "point", "word", "give", "effects", "words", "select", "shift", "same", "place", "composite", "holes", "inline", "become", "edit", "ungroup", "document", "sheet", "export"]),
        HelpPage(slug: "tints", title: "Using the Tints panel", group: "Color", summary: "A tint is a lighter version of a color: the same ink, printed at a percentage.  A 40% tint of your brand blue is still your brand blue at the press -- one plate, screened -- which is why tints, and not paler mixes, are how print work gets its lighter shades.  In WireTuner a tint always belongs to a base color.  Change the base and every tint of it changes; remove the base and its tints go with it.  The Tints panel makes, applies and names tints; show or hide it with Window Tints.",
                 headings: ["The panel", "Making and applying a tint", "Removing tints and bases", "Working with others"],
                 keywords: ["tint", "color", "base", "panel", "tints", "swatches", "well", "percentage", "colors", "swatch", "drag", "named", "onto", "unnamed", "same", "toward", "click", "apply", "objects", "brand", "blue", "applies", "pop-up", "preset", "slider", "split", "choose", "fill", "stroke", "spot", "process", "option", "restore", "lighter", "still", "press", "mixes", "change", "every", "changes"]),
        HelpPage(slug: "toolbars", title: "Toolbars and the Tools panel", group: "Basics", summary: "Toolbars put commands and tools where the pointer already is.  WireTuner has seven: the Main toolbar across the top of the document window, the Tools panel down its left edge, and five smaller toolbars -- Text, Info, Envelope, Extension Tools and Extension Operations -- that you show when you need them.  Any toolbar can float or dock; all of them can be customized (Customizing your environment).  This page describes each toolbar and lists every tool in the Tools panel with its shortcut and the page that documents it.",
                 headings: ["Showing, hiding, docking", "The Main toolbar", "The Tools panel", "The Text toolbar", "The Info toolbar", "The Envelope toolbar", "The Extension Tools and Extension Operations toolbars", "Working with others"],
                 keywords: ["tools", "tool", "panel", "toolbar", "color", "path", "draw", "flyout", "paths", "document", "opens", "object", "shortcut", "snap", "effects", "view", "toolbars", "pointer", "choose", "objects", "stroke", "freeform", "default", "select", "zoom", "points", "shift", "window", "extension", "show", "every", "drawing", "main", "left", "fill", "cols", "dragging", "rectangles", "applying", "grid"]),
        HelpPage(slug: "tracing", title: "Tracing images", group: "Imported artwork", summary: "The Trace tool turns pixels into paths.  Point it at a scanned logo, a hand-drawn sketch or a photograph and it produces filled or stroked paths that follow the shapes it finds, ready to edit with every path tool.  It can trace everything inside a marquee, or only an area of similar color you pick with its wand, and it traces anything on the page -- an imported image, but also WireTuner objects and text, which it treats as a picture of themselves.",
                 headings: ["Preparing an image to trace", "Setting the Trace tool options", "Tracing an area", "Tracing an area of color", "Working with others"],
                 keywords: ["trace", "colors", "color", "paths", "path", "image", "tool", "pixels", "result", "traces", "wand", "tracing", "objects", "everything", "options", "regions", "selection", "selected", "filled", "every", "inside", "area", "line", "tracer", "stroke", "traced", "follow", "wiretuner", "works", "photographs", "tolerance", "classic", "pixel", "become", "around", "region", "edge", "nothing", "select", "produces"]),
        HelpPage(slug: "transforming", title: "Transforming objects", group: "Objects", summary: "Transforming is moving, rotating, scaling, skewing and reflecting.  WireTuner offers three ways to do each: the transformation tools, for dragging about a point you choose; the Transform panel, for exact numbers and for making transformed copies; and the transform handles, which appear around a double-clicked object and let you do all five without changing tools.  Whichever you use, the object stays what it was -- a rotated rectangle is still a rectangle with a corner radius you can edit.",
                 headings: ["The transformation tools", "The Transform panel", "Transform handles", "Repeating a transformation", "Constrain angle", "Other transformation tools", "Working with others"],
                 keywords: ["transform", "selection", "center", "object", "rotate", "handles", "scale", "press", "tool", "point", "panel", "copies", "rotation", "transformation", "skew", "drag", "shift", "double-click", "reflect", "move", "path", "tools", "cols", "moving", "dragging", "around", "handle", "flips", "across", "angle", "horizontal", "copy", "clipping", "positive", "pointer", "show", "extensions", "scaling", "skewing", "wiretuner"]),
        HelpPage(slug: "transparency", title: "Transparency", group: "Effects", summary: "Transparency lets an object, or one of its fills or strokes, show what lies behind it.  In WireTuner transparency is a live effect: an attribute in the Object panel's appearance list, next to strokes, fills and the other effects on Live vector effects.  There is no separate opacity slider on the object -- the Basic transparency effect is the opacity, and because it is an effect you can put it on the object as a whole, on a single fill, or on a stroke, and stack it above or below other effects.  Three kinds are available:",
                 headings: ["Basic transparency", "Feather", "Gradient mask", "How transparency composites", "Working with others"],
                 keywords: ["transparency", "gradient", "object", "fill", "shape", "effect", "effects", "fills", "stroke", "feather", "mask", "transparent", "basic", "strokes", "same", "fade", "stops", "whole", "type", "select", "choose", "opaque", "radius", "gray", "show", "live", "slider", "click", "value", "fully", "drag", "raster", "resolution", "ramp", "shows", "group", "merge", "lets", "lies", "wiretuner"]),
        HelpPage(slug: "type-specifications", title: "Setting type specifications", group: "Type", summary: "Type specifications are the character-level settings: which font, how big, which face, how far apart the lines and letters sit, where the baseline is, and how wide the glyphs are drawn.  They apply to whatever is selected -- a range with the Text tool, or every character in the blocks selected with the Pointer tool.  With no selection they set the defaults for text you create next (Default attributes).  Where to find the controls is on The type adjustment tools; this page is what each one means.",
                 headings: ["Font, size and style", "Variable font axes", "OpenType features", "Alignment", "Leading", "Kerning and range kerning", "Baseline shift", "Horizontal scale", "Text effects and text styles", "How settings spread as you type", "Finding and replacing type attributes", "Working with others"],
                 keywords: ["font", "type", "size", "choose", "panel", "range", "style", "characters", "selected", "family", "face", "selection", "object", "document", "value", "change", "pop-up", "section", "bold", "axis", "small", "leading", "baseline", "every", "default", "find", "click", "fonts", "same", "below", "setting", "ligatures", "block", "replace", "settings", "tool", "pick", "toolbar", "field", "axes"]),
        HelpPage(slug: "type-tools", title: "The type adjustment tools", group: "Type", summary: "Type is adjusted from four places that all do the same things: the Text section of the Object panel (the most complete), the Text toolbar (the quickest), the Text menu (with keyboard shortcuts), and the text block's own handles (for leading and kerning by eye).  This page maps those four places; the meaning of each setting is on Setting type specifications, Paragraphs and Tabs, indents and margins.",
                 headings: ["The Text section of the Object panel", "The Text toolbar", "The Text menu", "Adjusting by dragging", "Adjusting with the keyboard", "Working with others"],
                 keywords: ["shift", "block", "family", "font", "type", "size", "leading", "path", "option", "style", "same", "kerning", "selected", "dragging", "panel", "range", "control", "list", "center", "point", "characters", "section", "object", "toolbar", "handles", "tool", "shows", "field", "pop-up", "value", "selection", "cols", "effect", "whole", "face", "points", "preset", "convert", "baseline", "handle"]),
        HelpPage(slug: "typeface-documents", title: "Typeface documents", group: "Typeface documents", summary: "A typeface document is a WireTuner document whose pages are glyphs.  Everything you know from illustration documents still applies -- the Pen tool, paths, layers, guides, booleans, expanded strokes, copy and paste -- but each glyph is its own small canvas measured in font units, with a baseline, an x-height and an advance width instead of a paper size, and the document window shows a grid of glyphs instead of page thumbnails.  From the same document you generate installable OTF, TTF and WOFF2 fonts, or exchange a UFO package with other font editors.",
                 headings: ["Document kinds", "Creating a typeface document", "How a typeface document differs", "Bringing artwork into a glyph", "The workflow in one page", "Working with others"],
                 keywords: ["glyph", "document", "font", "typeface", "units", "glyphs", "same", "grid", "choose", "every", "illustration", "sheet", "canvas", "window", "sketches", "layers", "copy", "metrics", "converting", "convert", "fonts", "kind", "panel", "origin", "pasteboard", "working", "features", "file", "point", "tool", "paths", "baseline", "x-height", "instead", "generate", "basic", "latin", "view", "everyone", "editing"]),
        HelpPage(slug: "undo", title: "Undoing actions", group: "Objects", summary: "Edit Undo takes back your last action; Edit Redo puts it back.  The menu names the action (Undo Rotate, Undo Paste 3 objects) so you can see what you are about to undo.  Undo reaches back through everything you have done in the document -- across saves, which happen continuously, and across quitting and relaunching WireTuner.",
                 headings: ["Undo in a shared document", "Offline"],
                 keywords: ["undo", "edit", "action", "back", "history", "redo", "change", "object", "undoing", "menu", "document", "wiretuner", "same", "changed", "last", "paste", "reaches", "everything", "across", "saves", "command", "nothing", "something", "list", "panel", "actions", "revert", "never", "people", "moved", "still", "undone", "item", "collaborator", "takes", "puts", "names", "rotate", "objects", "happen"]),
        HelpPage(slug: "urls", title: "Attaching links to objects and text", group: "Web and animation", summary: "Any object or run of text in a WireTuner document can carry a web link.  Links do nothing on the canvas -- clicking a linked object selects it, as always -- but they survive export: in a PDF the object becomes a clickable region, in an SVG it becomes an anchor, and on a published web page it becomes part of an image map.  Links are attached and inspected in the Navigation panel, which also lists every link already used in the document, finds the objects that use one, and rewrites a link everywhere it appears.  The same panel holds the page-to-page links described in Adding interactivity.",
                 headings: ["The Navigation panel", "Attaching a link", "Finding and updating links", "Seeing which objects are linked", "How links survive export", "Working with others"],
                 keywords: ["link", "object", "links", "every", "selected", "field", "panel", "linked", "becomes", "navigation", "objects", "same", "shows", "menu", "find", "range", "block", "html", "document", "name", "characters", "group", "adding", "window", "element", "output", "area", "words", "type", "pop-up", "inside", "press", "return", "fill", "export", "clickable", "published", "image", "lists", "everywhere"]),
        HelpPage(slug: "vector-basics", title: "Vector basics", group: "Drawing", summary: "Everything you draw in WireTuner is a path: a chain of points joined by straight or curved segments.  A rectangle, a spiral, a letterform converted to outlines and a freehand scribble are all paths, and every drawing tool on the following pages is a different way of placing points.  Because a path is described by its points rather than by pixels, it stays crisp at any zoom level and on any printer, and a document full of them is small.  This page explains what a path is made of, how WireTuner shows it to you, and which of its properties you can set in the Object panel.  Bitmap images -- photographs and scans -- can be imported, traced and placed alongside your paths; see Importing artwork and Tracing.",
                 headings: ["Paths, points and segments", "Point types", "Path and point display", "Path properties in the Object panel", "Working with others"],
                 keywords: ["path", "point", "points", "paths", "handles", "segment", "contours", "draw", "closed", "open", "wiretuner", "object", "curve", "fill", "straight", "direction", "curved", "panel", "drag", "contour", "corner", "change", "settings", "same", "line", "beginning", "whether", "tools", "editing", "type", "segments", "every", "shows", "properties", "handle", "back", "runs", "place", "todo", "screenshot"]),
        HelpPage(slug: "web-compression", title: "Compressing artwork for the web", group: "Web and animation", summary: "Artwork headed for a web page has to be small and has to look right in a browser.  WireTuner gives you two ways to get there: keep the artwork as vectors (SVG, which browsers render natively and which stays sharp at every size) or rasterize it into a compressed bitmap.  This page is about choosing between them and, when you rasterize, choosing a format.  The export procedures and every option of each format live on xref:export-bitmap.adoc[Exporting bitmap images] and Exporting vector formats; xref:publish-html.adoc[Publishing as HTML] applies these choices to a whole document at once.",
                 headings: ["Vector or bitmap?", "Choosing a bitmap format", "Settings that matter", "Web presets", "Working with others"],
                 keywords: ["every", "export", "jpeg", "color", "transparency", "artwork", "size", "bitmap", "format", "document", "same", "file", "exporting", "images", "webp", "sheet", "presets", "browser", "wiretuner", "browsers", "sharp", "rasterize", "xref", "adoc", "avif", "gradients", "flat", "smaller", "objects", "photographs", "lossy", "quality", "matter", "colors", "preset", "small", "look", "keep", "vectors", "choosing"]),
        HelpPage(slug: "workspace", title: "The workspace", group: "Basics", summary: "WireTuner is a vector drawing application: artwork is made of paths, text and images described mathematically, so it scales to any size and prints at any resolution without losing detail. Everything you do happens in one place -- the document window -- surrounded by panels, toolbars and the menu bar.  This page walks through that window: the pasteboard, the tab bar that holds several open documents, the status bar, and the command palette.",
                 headings: ["The document window", "Working with others"],
                 keywords: ["document", "window", "open", "status", "palette", "panels", "changes", "view", "command", "current", "press", "panel", "choose", "pasteboard", "right", "shows", "canvas", "click", "wiretuner", "documents", "opens", "offline", "magnification", "setting", "commands", "rotate", "without", "toolbars", "menu", "holds", "several", "todo", "screenshot", "tools", "left", "bottom", "name", "sync", "every", "change"]),
